package com.desktodo.app;

import android.content.res.ColorStateList;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;

/** Shared native presentation: 8dp spacing, 48dp targets and explicit hierarchy. */
final class AppUi {
 static final int INK=Color.rgb(27,46,39),MUTED=Color.rgb(103,113,106),PAPER=Color.rgb(248,247,243),GREEN=Color.rgb(32,87,65),SOFT=Color.rgb(237,242,236),LINE=Color.rgb(229,233,225),DANGER=Color.rgb(153,53,44);
 static GradientDrawable shape(MainActivity a,int color,int radius,boolean border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(a.dp(radius));if(border)d.setStroke(a.dp(1),LINE);return d;}
 static android.graphics.drawable.Drawable press(MainActivity a,int color,int radius,boolean border){return new RippleDrawable(ColorStateList.valueOf(0x24325e49),shape(a,color,radius,border),null);}
 static Button button(MainActivity a,String title,boolean primary,Runnable action){Button b=new Button(a);b.setText(title);b.setTextSize(15);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setStateListAnimator(null);b.setTextColor(primary?Color.WHITE:GREEN);b.setMinWidth(a.dp(48));b.setMinimumWidth(a.dp(48));b.setMinHeight(a.dp(48));b.setMinimumHeight(a.dp(48));b.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));b.setBackground(press(a,primary?GREEN:Color.WHITE,14,!primary));b.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));b.setOnClickListener(v->action.run());return b;}
 static void attach(MainActivity a,LinearLayout parent,View view){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,a.dp(8),0,0);parent.addView(view,p);}
 static LinearLayout row(MainActivity a,LinearLayout parent,String title,String detail,Runnable action){
  if(parent.getChildCount()>1){View line=new View(a);line.setBackgroundColor(LINE);parent.addView(line,new LinearLayout.LayoutParams(-1,a.dp(1)));}
  LinearLayout row=new LinearLayout(a);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(a.dp(2),a.dp(11),a.dp(2),a.dp(11));row.setMinimumHeight(a.dp(60));row.setBackground(press(a,Color.TRANSPARENT,10,false));LinearLayout copy=new LinearLayout(a);copy.setOrientation(1);TextView h=a.text(title,15,INK);h.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));copy.addView(h);if(!detail.isEmpty())copy.addView(a.text(detail,12,MUTED));row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=a.text("›",23,MUTED);arrow.setPadding(a.dp(12),0,0,0);arrow.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);row.addView(arrow);row.setFocusable(true);row.setContentDescription(title+"，"+detail);row.setOnClickListener(v->action.run());parent.addView(row);return row;
 }
 static void section(MainActivity a,String title){TextView t=a.text(title,15,INK);t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));t.setPadding(a.dp(2),a.dp(18),0,a.dp(5));a.body.addView(t);}
 static View iconButton(MainActivity a,int icon,String description,Runnable action){View v=new ActionIcon(a,icon,GREEN);v.setMinimumWidth(a.dp(48));v.setMinimumHeight(a.dp(48));v.setContentDescription(description);v.setFocusable(true);v.setBackground(press(a,Color.TRANSPARENT,14,false));v.setAccessibilityDelegate(new View.AccessibilityDelegate(){public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(Button.class.getName());}});v.setOnClickListener(w->action.run());return v;}
 static final class ActionIcon extends View {final Paint p=new Paint(3);final int icon;ActionIcon(MainActivity a,int icon,int color){super(a);this.icon=icon;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(1.5f));}protected void onDraw(Canvas c){super.onDraw(c);float x=getWidth()/2f,y=getHeight()/2f,r=getResources().getDisplayMetrics().density*9;if(icon==0)c.drawCircle(x,y,r,p);else{p.setStyle(Paint.Style.FILL);for(int n=-1;n<=1;n++)c.drawCircle(x+n*r*.6f,y,r*.13f,p);p.setStyle(Paint.Style.STROKE);}}}
 static void tile(MainActivity a,LinearLayout row,String title,String detail,int icon,Runnable action){LinearLayout tile=new LinearLayout(a);tile.setOrientation(1);tile.setPadding(a.dp(14),a.dp(13),a.dp(14),a.dp(13));tile.setMinimumHeight(a.dp(108));tile.setBackground(press(a,Color.WHITE,18,true));LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);NavIcon symbol=new NavIcon(a,icon,GREEN);heading.addView(symbol,new LinearLayout.LayoutParams(a.dp(20),a.dp(20)));TextView h=a.text(title,14,INK);h.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(0,-2,1);hp.leftMargin=a.dp(7);heading.addView(h,hp);tile.addView(heading);TextView d=a.text(detail,12,MUTED);d.setPadding(0,a.dp(9),0,0);tile.addView(d);tile.setContentDescription(title+"，"+detail);tile.setFocusable(true);tile.setOnClickListener(v->action.run());LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);if(row.getChildCount()>0)params.leftMargin=a.dp(10);row.addView(tile,params);}
 static LinearLayout navigation(MainActivity a){LinearLayout bar=new LinearLayout(a);bar.setPadding(a.dp(10),a.dp(3),a.dp(10),a.dp(3));bar.setBackgroundColor(Color.WHITE);for(int i=0;i<3;i++){String name=new String[]{"工作台","助手","我的"}[i];boolean selected=a.topPage().equals(name);LinearLayout item=new LinearLayout(a);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setMinimumHeight(a.dp(64));item.setPadding(0,a.dp(5),0,a.dp(5));item.setBackground(press(a,Color.TRANSPARENT,18,false));FrameLayout pill=new FrameLayout(a);pill.setBackground(shape(a,selected?SOFT:Color.TRANSPARENT,14,false));FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(a.dp(22),a.dp(22),Gravity.CENTER);pill.addView(new NavIcon(a,i,selected?GREEN:MUTED),ip);item.addView(pill,new LinearLayout.LayoutParams(a.dp(54),a.dp(28)));TextView label=a.text(name,11,selected?GREEN:MUTED);label.setGravity(Gravity.CENTER);label.setTypeface(Typeface.create(selected?"sans-serif-medium":"sans-serif",Typeface.NORMAL));label.setPadding(0,a.dp(4),0,0);item.addView(label);item.setContentDescription(name);item.setSelected(selected);item.setFocusable(true);item.setOnClickListener(v->a.openPage(name));bar.addView(item,new LinearLayout.LayoutParams(0,-2,1));}return bar;}
 static final class NavIcon extends View {final Paint p=new Paint(3);final int type;NavIcon(MainActivity a,int type,int color){super(a);this.type=type;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/24f,getHeight()/24f);if(type==0){c.drawRoundRect(4,3,20,21,3,3,p);for(int y:new int[]{8,12,16}){c.drawLine(8,y,9,y,p);c.drawLine(12,y,16,y,p);}}else if(type==1){Path path=new Path();path.moveTo(12,2);path.lineTo(15,9);path.lineTo(22,12);path.lineTo(15,15);path.lineTo(12,22);path.lineTo(9,15);path.lineTo(2,12);path.lineTo(9,9);path.close();c.drawPath(path,p);}else if(type==2){c.drawCircle(12,7,4,p);c.drawArc(4,13,20,26,190,160,false,p);}else if(type==3){c.drawRoundRect(4,3,20,21,2,2,p);c.drawLine(8,9,16,9,p);c.drawLine(12,13,12,18,p);c.drawLine(9.5f,15.5f,14.5f,15.5f,p);}else if(type==4){c.drawRoundRect(4,4,20,21,2,2,p);c.drawLine(4,9,20,9,p);c.drawLine(8,2,8,6,p);c.drawLine(16,2,16,6,p);c.drawLine(8,15,11,18,p);c.drawLine(11,18,16,12,p);}else{c.drawCircle(12,13,8,p);c.drawLine(12,13,12,8,p);c.drawLine(12,13,16,15,p);if(type==5){c.drawLine(9,2,15,2,p);}else{c.drawLine(2,5,6,5,p);c.drawLine(2,5,2,9,p);}}c.restore();}}
 static final class LayoutThumb extends View {final String kind;final boolean selected;final Paint p=new Paint(3);LayoutThumb(MainActivity a,String kind,boolean selected){super(a);this.kind=kind;this.selected=selected;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/160f,getHeight()/96f);p.setColor(Color.WHITE);c.drawRoundRect(1,1,159,95,5,5,p);p.setColor(LINE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);c.drawRoundRect(1,1,159,95,5,5,p);p.setStyle(Paint.Style.FILL);p.setColor(selected?GREEN:MUTED);c.drawRoundRect(9,9,43,15,2,2,p);p.setColor(SOFT);c.drawRect(9,21,151,24,p);int right=kind.equals("minimal")?151:kind.equals("pomodoro")?88:kind.equals("focus")||kind.equals("agenda")?111:100;for(int y:new int[]{34,48,62}){p.setColor(LINE);c.drawRoundRect(9,y,15,y+6,2,2,p);p.setColor(selected?GREEN:MUTED);c.drawRoundRect(21,y,right,y+4,2,2,p);}if(right<150){p.setColor(SOFT);c.drawRoundRect(right+8,32,151,69,3,3,p);}p.setColor(LINE);c.drawRoundRect(9,80,151,87,2,2,p);c.restore();}}
}
